import re
from datetime import date
from decimal import Decimal, InvalidOperation

CENT = Decimal("0.01")
_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


def _cents_to_decimal(cents: int) -> Decimal:
    if cents == 0:
        return Decimal("0.00")
    sign_str = "-" if cents < 0 else ""
    a = abs(cents)
    q, r = divmod(a, 100)
    return Decimal(f"{sign_str}{q}.{r:02d}")


def _parse_money(value, name):
    if not isinstance(value, str):
        raise ValueError(f"{name} must be a string")
    try:
        d = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid {name}: {value!r}") from None
    if not d.is_finite():
        raise ValueError(f"{name} must be finite")
    tup = d.as_tuple()
    exp = tup.exponent
    digits = tup.digits
    if exp < -2:
        k = -(exp + 2)
        if len(digits) > k:
            if any(digits[-k:]):
                raise ValueError(f"{name} must have at most 2 decimal places")
            leading = digits[:len(digits) - k]
            if leading:
                cents_abs = int("".join(map(str, leading)))
            else:
                cents_abs = 0
        else:
            if any(digits):
                raise ValueError(f"{name} must have at most 2 decimal places")
            cents_abs = 0
    else:
        digits_str = "".join(map(str, digits)) if digits else "0"
        cents_abs = int(digits_str) if digits_str else 0
        shift = exp + 2
        if shift > 0:
            cents_abs = cents_abs * (10 ** shift)
    if cents_abs == 0:
        cents = 0
    else:
        cents = -cents_abs if tup.sign else cents_abs
    quantized = _cents_to_decimal(cents)
    return quantized, cents


def _money(value, name, allow_zero_amount=True):
    quantized, _ = _parse_money(value, name)
    return quantized


def _date(value, name):
    if not isinstance(value, str):
        raise ValueError(f"{name} must be YYYY-MM-DD")
    if _DATE_RE.fullmatch(value) is None:
        raise ValueError(f"{name} must be YYYY-MM-DD")
    try:
        date(int(value[0:4]), int(value[5:7]), int(value[8:10]))
    except ValueError:
        raise ValueError(f"invalid {name}: {value!r}") from None
    return value


def running_balance(transactions: list[dict], opening_balance: str) -> list[dict]:
    opening, opening_cents = _parse_money(opening_balance, "opening_balance")
    if not isinstance(transactions, list):
        raise ValueError("transactions must be a list")
    seen = set()
    normalized = []
    for tx in transactions:
        if not isinstance(tx, dict):
            raise ValueError("each transaction must be a dict")
        for key in ("id", "value_date", "booking_date", "amount"):
            if key not in tx:
                raise ValueError(f"missing key: {key}")
        tx_id = tx["id"]
        if not isinstance(tx_id, str) or tx_id == "":
            raise ValueError("id must be a non-empty string")
        if tx_id in seen:
            raise ValueError(f"duplicate id: {tx_id!r}")
        seen.add(tx_id)
        value_date = _date(tx["value_date"], "value_date")
        booking_date = _date(tx["booking_date"], "booking_date")
        amount, amount_cents = _parse_money(tx["amount"], "amount")
        normalized.append({"id": tx_id, "value_date": value_date, "booking_date": booking_date, "amount": amount, "_cents": amount_cents})
    normalized.sort(key=lambda r: (r["value_date"], r["booking_date"], r["id"]))
    rows = []
    balance_cents = opening_cents
    for r in normalized:
        balance_cents = balance_cents + r["_cents"]
        balance = _cents_to_decimal(balance_cents)
        rows.append({"id": r["id"], "value_date": r["value_date"], "booking_date": r["booking_date"], "amount": r["amount"], "balance": balance})
    return rows


def closing_balance(transactions: list[dict], opening_balance: str) -> Decimal:
    rows = running_balance(transactions, opening_balance)
    if not rows:
        return _money(opening_balance, "opening_balance")
    return rows[-1]["balance"]
